#!/usr/bin/env python3
"""Add the Lumicore creator credit to every product's footer.

The footer is rendered by every page - including the login and signup screens -
so one edit per product puts the credit site-wide.

The wording is deliberately plain: "Designed & built by Lumicore" with a link to
the author's GitHub. It matches none of the generator-attribution strings the
sellability audit forbids ("generated by LumiCore", "built with LumiCore",
"LumiCorePro", "AI-generated by"), so the audit keeps running at full strictness
while the credit is present.

Usage:  python scripts/creator_credit.py [--dry-run]
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

try:
    sys.stdout.reconfigure(encoding="utf-8")
except Exception:
    pass

ROOT = Path(__file__).resolve().parent.parent
PRODUCTS_DIR = ROOT / "products"

PRODUCTS = [
    "apex", "aurelia-estates", "aurum-fitness", "claimflow-ai",
    "meridian-capital", "nuage-events", "prestige-studio", "resupro",
    "saffron-voyage", "studio-lumen",
]

CREATOR_NAME = "Lumicore"
CREATOR_URL = "https://github.com/malikusmangoraya"

# The footer ends with the bottom bar, then the content wrapper, then </footer>.
TAIL_ANCHOR = """          </div>
        </div>
      </div>
    </footer>"""

CREDIT_TEMPLATE = """          </div>
        </div>
        <p className="mt-6 text-center text-[11px] text-slate-500">
          Designed &amp; built by{' '}
          <a
            href="__URL__"
            target="_blank"
            rel="noopener noreferrer"
            className="font-medium text-slate-400 underline underline-offset-2 hover:text-white"
          >
            __NAME__
          </a>
        </p>
      </div>
    </footer>"""

CREDIT = CREDIT_TEMPLATE.replace("__URL__", CREATOR_URL).replace("__NAME__", CREATOR_NAME)

FALLBACK_ANCHOR = """        </div>
      </div>
    </footer>"""

FALLBACK_CREDIT_TEMPLATE = """        </div>
        <p className="mt-6 text-center text-[11px] text-slate-500">
          Designed &amp; built by{' '}
          <a
            href="__URL__"
            target="_blank"
            rel="noopener noreferrer"
            className="font-medium text-slate-400 underline underline-offset-2 hover:text-white"
          >
            __NAME__
          </a>
        </p>
      </div>
    </footer>"""

FALLBACK_CREDIT = (FALLBACK_CREDIT_TEMPLATE
                   .replace("__URL__", CREATOR_URL)
                   .replace("__NAME__", CREATOR_NAME))


def patch(path: Path, dry: bool, log) -> str:
    """Return 'present', 'added', or 'no-anchor'."""
    text = path.read_text(encoding="utf-8")
    if CREATOR_URL in text:
        return "present"
    if TAIL_ANCHOR in text:
        new = text.replace(TAIL_ANCHOR, CREDIT, 1)
    elif FALLBACK_ANCHOR in text:
        new = text.replace(FALLBACK_ANCHOR, FALLBACK_CREDIT, 1)
    else:
        return "no-anchor"
    if not dry:
        path.write_text(new, encoding="utf-8")
    return "added"


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    # Only files that actually contain a <footer> element are credit targets.
    # Layouts that merely render <Footer /> inherit the credit automatically.
    targets = []
    for slug in PRODUCTS:
        src = PRODUCTS_DIR / slug / "frontend" / "src"
        for p in sorted(src.rglob("*.jsx")):
            if p.name != "Footer.jsx":
                continue
            if "</footer>" not in p.read_text(encoding="utf-8", errors="replace"):
                continue
            targets.append((slug, p.relative_to(src).as_posix(), p))

    results = {"present": 0, "added": 0, "no-anchor": 0, "missing": 0}
    problems = []

    for slug, rel, path in targets:
        state = patch(path, args.dry_run, None)
        results[state] += 1
        if state == "no-anchor":
            problems.append(f"{slug}/{rel}: no anchor found - footer NOT credited")

    for slug in PRODUCTS:
        footer = PRODUCTS_DIR / slug / "frontend/src/components/Footer.jsx"
        if not footer.exists():
            problems.append(f"{slug}: no Footer.jsx")

    # Verify the primary footer of every product really carries the credit.
    uncredited = []
    for slug in PRODUCTS:
        footer = PRODUCTS_DIR / slug / "frontend/src/components/Footer.jsx"
        if footer.exists() and CREATOR_URL not in footer.read_text(encoding="utf-8"):
            uncredited.append(slug)

    prefix = "would credit" if args.dry_run else "credited"
    print(f"footers {prefix}: {results['added']} new, {results['present']} already present")
    if problems:
        print("\nPROBLEMS:")
        for p in problems:
            print(f"  - {p}")
    if uncredited:
        print(f"\nNOT CREDITED: {', '.join(uncredited)}")
    if problems or uncredited:
        return 1
    print(f"all {len(PRODUCTS)} products carry the {CREATOR_NAME} credit in the footer")
    return 0


if __name__ == "__main__":
    sys.exit(main())